    async function sbFetch(path, opts = {}) {
      const res = await fetch(SUPABASE_URL + path, Object.assign({}, opts, {
        headers: authHeaders(opts.headers || {})
      }));
      const txt = await res.text();
      let data = null;
      try { data = txt ? JSON.parse(txt) : null; } catch (e) { data = txt; }
      if (!res.ok) {
        const msg = (data && (data.msg || data.error_description || data.message || data.error)) || ("HTTP " + res.status);
        throw new Error(msg);
      }
      return data;
    }

    async function checkUsernameAvailableRpc(username) {
      const clean = (username || "").trim().replace(/^@/, "").toLowerCase();
      if (clean.length < 3 || clean.length > 20) return false;
      try {
        const res = await fetch(SUPABASE_URL + "/rest/v1/rpc/username_available", {
          method: "POST",
          headers: {
            "apikey": SUPABASE_ANON_KEY,
            "Authorization": "Bearer " + SUPABASE_ANON_KEY,
            "Content-Type": "application/json"
          },
          body: JSON.stringify({ p_username: clean })
        });
        if (!res.ok) return false;
        const data = await res.json();
        return data === true;
      } catch (e) {
        return false;
      }
    }

    async function lookupEmailByUsername(username) {
      const u = username.trim().toLowerCase().replace(/^@/, "");
      try {
        const res = await fetch(SUPABASE_URL + "/functions/v1/login-lookup", {
          method: "POST",
          headers: { "apikey": SUPABASE_KEY, "Authorization": "Bearer " + SUPABASE_KEY, "Content-Type": "application/json" },
          body: JSON.stringify({ username: u })
        });
        if (res.ok) {
          const j = await res.json();
          if (j && j.email) return j.email;
        }
      } catch (e) {}
      return null;
    }

    async function signInWithEmailPassword(identifier, password) {
      let email = identifier.trim();
      if (!email.includes("@")) {
        const found = await lookupEmailByUsername(email);
        if (!found) throw new Error("No account found for @" + email + ". Try your email address.");
        email = found;
      }
      const data = await sbFetch("/auth/v1/token?grant_type=password", {
        method: "POST",
        body: JSON.stringify({ email, password })
      });
      await activateDesktopSession(data);
    }

