        const dh2 = x25519(b64d(baseKp.priv), peerIdent32);
        const dh3 = x25519(b64d(baseKp.priv), peerSpk32);
        const dhParts = [discont, dh1, dh2, dh3];
        if (otpPub32) dhParts.push(x25519(b64d(baseKp.priv), otpPub32));
