    // Crop image file to square JPEG (256x256) on canvas and upload to avatars bucket
    async function cropAndUploadAvatar(file) {
      const imgUrl = URL.createObjectURL(file);
      const img = await new Promise((resolve, reject) => {
        const el = new Image();
        el.onload = () => resolve(el);
        el.onerror = reject;
        el.src = imgUrl;
      });
      const size = Math.min(img.width, img.height);
      const sx = Math.floor((img.width - size) / 2);
      const sy = Math.floor((img.height - size) / 2);
      const canvas = document.createElement("canvas");
      canvas.width = 256;
      canvas.height = 256;
      const ctx = canvas.getContext("2d");
      ctx.drawImage(img, sx, sy, size, size, 0, 0, 256, 256);
      URL.revokeObjectURL(imgUrl);
      const blob = await new Promise(res => canvas.toBlob(res, "image/jpeg", 0.88));
      const bytes = new Uint8Array(await blob.arrayBuffer());
      const path = `u_${state.userId}_${Date.now()}.jpg`;
      const upRes = await fetch(SUPABASE_URL + "/storage/v1/object/avatars/" + path, {
        method: "POST",
        headers: authHeaders({ "x-upsert": "true", "Content-Type": "image/jpeg" }),
        body: bytes
      });
      if (!upRes.ok) throw new Error("Avatar upload failed");
      const publicUrl = SUPABASE_URL + "/storage/v1/object/public/avatars/" + path;
      await sbFetch("/rest/v1/profiles?id=eq." + state.userId, {
        method: "PATCH",
        body: JSON.stringify({ avatar_url: publicUrl })
      });
      return publicUrl;
    }

