          b.querySelector("#btnRestoreCloudBackup").addEventListener("click", async () => {
            const rawKey = b.querySelector("#inpRestoreRecoveryKey").value.trim();
            if (!rawKey) return;
            try {
              const rows = await sbFetch("/rest/v1/backups?user_id=eq." + state.userId + "&select=blob&limit=1");
              if (!Array.isArray(rows) || !rows[0]?.blob) throw new Error("No cloud backup found for this account");
              const encBytes = SangamCrypto.b64d(rows[0].blob);
              const normalized = rawKey.replace(/[^A-Za-z0-9]/g, "");
              let decBytes = null;
              for (const cand of [normalized, rawKey]) {
                try { decBytes = await SangamCrypto.backupDecrypt(encBytes, cand); break; } catch (_e) {}
              }
              if (!decBytes) throw new Error("That recovery key does not open this backup");
              const payload = JSON.parse(new TextDecoder().decode(decBytes));
              if (payload && payload.envelopes) {
                Object.assign(state.outbox, payload.envelopes);
                safeSet("sangam_win_outbox", JSON.stringify(state.outbox));
              }
              state.syncKey = normalized;
              safeSet("sangam_win_sync_key", normalized);
              await refreshAllData();
              showToast("Restored " + Object.keys(payload.envelopes || {}).length + " messages ✓");
            } catch (err) { showToast(err.message || "Could not restore backup"); }
          });
          b.querySelector("#btnSettingsDevices").addEventListener("click", () => openDevicesModal());
