      async function sendCurrentStageText() {
        const inp = document.getElementById("inpStageMessage");
        const txt = inp.value.trim();
        if (!txt || !state.activeChat) return;
        inp.value = "";
        const env = { t: "t", b: txt };
        if (state.replyTo) {
          env.q = state.replyTo.id;
          env.p = state.replyTo.quote;
          state.replyTo = null;
          document.getElementById("stageReplyBanner").classList.add("hidden");
        }
        try {
          await sendSangamEnvelope(
            state.activeChat.isGroup ? "" : state.activeChat.id,
            env,
            state.activeChat.isGroup ? state.activeChat.id : null
          );
        } catch (e) { showToast(e.message); }
      }

      document.getElementById("btnStageSend").addEventListener("click", sendCurrentStageText);
